["Happy cows","Keep the cows fed and the pails full."]]},{"stat":"made_cheese","target":2,"titles":[["Cheese board","Turn fresh milk into farmhouse cheese."],["Say cheese","The Dairy Barn’s finest, wheel after wheel."]]},{"stat":"made_flour","target":13,"titles":[["Flour power","Keep the Windmill turning and the flour sacks full."],["Mill and grind","Grain in, flour out, all day long."]]},{"stat":"produced","target":5,"titles":[["Busy kitchens","Keep your buildings humming and collect fresh batches."],["Workshop rush","Batch after batch from every building."]]},{"stat":"made_grainmeal","target":5,"titles":[["Grind it out","Wheat and barley into grain meal at the Windmill."],["Sails turning","The Windmill never stops today."]]},{"stat":"made_bread","target":3,"titles":[["Fresh from the oven","Warm bread from the Bakery for the whole village."],["Bread and butter","Flour and milk into golden loaves."]]},{"stat":"parallel_batches","target":4,"titles":[["Full steam ahead","Start batches while others are still running."],["Many hands","Keep every slot of your buildings busy."]]},{"stat":"made_salad","target":3,"titles":[["Salad bar","Fresh salads from the Packing Shed."],["Green and crisp","A salad for every lunch box."]]},{"stat":"made_fertilizer","target":4,"titles":[["Good soil","Natural fertilizer from the Windmill."],["Feed the fields","Fertilizer for every field on the farm."]]},{"stat":"made_goatmilk","target":3,"titles":[["Goat milk run","Fresh milk from the Goat Shed."],["Curious goats","Keep the goats happy and the pails full."]]}],[{"stat":"sold","target":30,"titles":[["Market day","Fill the stalls and sell, sell, sell."],["Open stalls","The market is busy. Bring everything you can."]]},{"stat":"earned","target":2500,"titles":[["Coin harvest","Earn coins at the market, with orders and with chores."],["Golden profits","A good day to fill the coin purse."]]},{"stat":"coins_spent","target":3000,"titles":[["Big spenders","Seeds, upgrades and new buildings: invest in your farm."],["Shopping spree","Put your coins to work on the farm."]]}],[{"stat":"chores","target":1,"titles":[["Helping hands","Lend a hand around the farm."],["Odd jobs","The little jobs that keep a farm running."]]},{"stat":"activities","target":1,"titles":[["A helping hand","Help at the greenhouse, the apiary, the paddock and the workshop."],["Around the farm","Lend a hand at every stop on the farm."]]},{"stat":"upgrades","target":1,"titles":[["Builders’ day","Make your buildings better and faster."],["Hammer time","Upgrade the buildings that work hardest for you."]]},{"stat":"activity_rounds","target":1,"titles":[["Grand tour","Help at all four stops for the round bonus."],["All around","The greenhouse, the apiary, the paddock and the workshop, in one round."]]},{"stat":"tractor","target":2,"titles":[["Tractor day","Let the tractor work the fields."],["Full throttle","Rows and rows, done in one go."]]}]],"2":[[{"stat":"made_stone","target":18,"titles":[["Quarry day","Dig stone, cart after cart, at the Mine."],["Rock solid","Good stone for paths, walls and kilns."]]},{"stat":"made_ironore","target":20,"titles":[["Iron rush","Send your miners down for iron ore."],["Ore cart","Cart after cart of iron ore from the Mine."]]},{"stat":"made_timber","target":25,"titles":[["Woodcutters’ day","Chop logs at the Lumber Camp."],["Into the woods","Fresh logs from the forest by the lake."]]},{"stat":"made_clay","target":20,"titles":[["Muddy boots","Dig clay from the pit for the Potter’s Kiln."],["Clay day","Wet clay by the cartload, ready for the kiln."]]}],[{"stat":"made_packedlunch","target":12,"titles":[["Lunch is packed","Hungry miners and woodcutters are waiting."],["Lunch break","A packed lunch for every worker in the village."]]},{"stat":"made_potatoes","target":30,"titles":[["Potato patch","Potatoes from the Village Fields, row after row."],["Spud season","Dig up potatoes for the canteen’s pasties."]]}],[{"stat":"village_batches","target":17,"titles":[["Busy village","Keep every place in the village working."],["Village at work","Collect batch after batch in every village place."]]},{"stat":"made_plank","target":7,"titles":[["Saw and sawdust","Logs into planks at the Lumber Camp."],["Plank by plank","Fresh planks for every new building in the village."]]},{"stat":"made_rooftile","target":8,"titles":[["Roof over our heads","Fire roof tiles at the Potter’s Kiln."],["Red rooftops","Tile after tile for the village roofs."]]}],[{"stat":"village_requests","target":1,"titles":[["Helping the village","Bring the villagers the goods they ask for."],["A busy square","Villagers are waiting at the market square with their requests."]]}],[{"stat":"lake_fish","target":2,"titles":[["Gone fishing","Row out on the village lake and cast your line."],["Lake day","Catch fish from the rowboat on the village lake."]]},{"stat":"upgrades","target":1,"titles":[["Builders’ day","Make your buildings better and faster."],["Hammer time","Upgrade the buildings that work hardest for you."]]}]]}';
 mix constant jsonb:='[["own","own","own","own"],["own","own","own","own"],["own","own","own","own"],["own","own","own","own"],["own","own","own","own"],["own","own","own","own"],["own","own","1","1"],["own","own","1","1"],["own","own","1","1"],["own","own","1","1"],["own","own","1","1"],["own","own","1","1"],["own","own","2","1"],["own","own","2","1"],["own","own","2","1"],["own","own","2","1"],["own","own","2","1"]]';
 grp int:=(n%5)::int; lg int; r bigint; src text; pool jsonb; kind jsonb; title jsonb; leagues jsonb:='[]'::jsonb;
begin
 -- The kind of play is the same for everyone this hour (fields, crops, buildings, market, helping out; in the village mine and
 -- forest, fields and kitchens, workshops, market square, around the village). 24 is not a multiple of 5, so an hour of the day
 -- gets another kind every day.
 for lg in 0..jsonb_array_length(pools)-1 loop
  -- Where this league's goal comes from this hour (29 Oct 2026): its own pool, or an older world's (the farm's, the village's).
  src:=mix->lg->>((abs(hashtextextended('harvest-hour-source:'||n||':'||lg,0))%jsonb_array_length(mix->lg))::int);
  pool:=case when src='own' then pools->lg->grp else older->src->grp end;
  r:=abs(hashtextextended('harvest-hour-event:'||n||':'||lg,0));
  kind:=pool->((r%jsonb_array_length(pool))::int);
  title:=kind->'titles'->(((r/7)%jsonb_array_length(kind->'titles'))::int);
  leagues:=leagues||jsonb_build_array(jsonb_build_object('title',title->>0,'description',title->>1,
   'objectives',jsonb_build_array(jsonb_build_object('stat',kind->>'stat','target',(kind->>'target')::int))));
 end loop;
 -- The event's own title and goal are the Sprout League's: admin screens and any older reader keep working.
 return jsonb_build_object('title',leagues->0->>'title','description',leagues->0->>'description','objectives',leagues->0->'objectives','leagues',leagues);
end $function$;

-- After-check, in the same transaction.
