,"made_milk","made_cheese","made_flour","produced","made_grainmeal","made_bread","parallel_batches","made_salad","made_fertilizer","made_goatmilk","sold","earned","coins_spent","chores","activities","activity_rounds","tractor"],["ship_loads","made_rope","made_barrel","harbour_batches","made_shipsbiscuits","harbour_sold","seal_pats","harbour_upgrades","made_stone","made_ironore","made_timber","made_clay","made_packedlunch","made_potatoes","village_batches","made_plank","made_rooftile","village_requests","lake_fish","upgrades","harvested","planted","watered","tended","fertilized","harvest_wheat","harvest_corn","harvest_lettuce","harvest_barley","made_eggs","made_feed","made_milk","made_cheese","made_flour","produced","made_grainmeal","made_bread","parallel_batches","made_salad","made_fertilizer","made_goatmilk","sold","earned","coins_spent","chores","activities","activity_rounds","tractor"]]'; b record; t jsonb; lg int; o jsonb; older int:=0; begin
 if (select md5(prosrc) from pg_proc where oid=to_regprocedure('public.harvest_event_pick(bigint)')) is distinct from 'c6cd5e4329816139b8256d5f77763c17' then raise exception 'public.harvest_event_pick(bigint) did not come out as generated'; end if;
 if exists(select 1 from pg_proc p where p.oid=to_regprocedure('public.harvest_event_pick(bigint)')
    and (p.prosecdef or p.provolatile<>'s' or p.proconfig is distinct from array['search_path=""'] or p.proacl::text is distinct from '{postgres=X/postgres,service_role=X/postgres}'))
  then raise exception 'the function header or grant changed'; end if;
 for b in select * from hour_mix_before loop
  t:=public.harvest_event_pick(b.n);
  if jsonb_array_length(t->'leagues')<>17 then raise exception 'hour %: not % leagues', b.n, 17; end if;
  -- The farm's leagues draw exactly as before.
  if (select jsonb_agg(x order by i) from jsonb_array_elements(t->'leagues') with ordinality e(x,i) where i<=6) is distinct from (select jsonb_agg(x order by i) from jsonb_array_elements(b.t->'leagues') with ordinality e(x,i) where i<=6)
   then raise exception 'hour %: a farm league''s goal changed', b.n; end if;
  for lg in 0..16 loop
   o:=t->'leagues'->lg->'objectives';
   if jsonb_array_length(o)<>1 or not allowed->lg ? (o->0->>'stat') or (o->0->>'target')::int<1 or coalesce(t->'leagues'->lg->>'title','')='' then raise exception 'hour % league %: % is not one of its goals', b.n, lg, o; end if;
   if lg>=6 and o is distinct from b.t->'leagues'->lg->'objectives' then older:=older+1; end if;
  end loop;
 end loop;
 -- In 48 hours some of the 11 higher leagues' goals come from an older world (about half of them do).
 if older=0 then raise exception 'no higher league drew another goal in 48 hours'; end if;
end $after$;
commit;
